SELECT gen_random_uuid()::text, 'formula', '$F = qE$', 'Force and Energy of a Charge in a Field', '$F = qE,\qquad W = qV,\qquad \tfrac12mv^2 = qV \text{ (from rest)}$', '$\text{N}$', 'The force a field puts on a charge, and the energy the charge gains crossing a potential difference.', '[{"symbol":"$q$","meaning":"charge","unit":"$\\text{C}$"},{"symbol":"$E$","meaning":"field","unit":"$\\text{V/m}$"},{"symbol":"$V$","meaning":"potential difference crossed","unit":"$\\text{V}$"}]'::jsonb, 'An electron through 1 V gains 1 eV = 1.602 × 10⁻¹⁹ J.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'coulomb''s law' AND s."active"), NULL, false, 'PENDING', now(), now()
