SELECT gen_random_uuid()::text, 'formula', '$E = \frac{\lambda}{2\pi\varepsilon r}$', 'Field of Line and Sheet Charges', '$\text{line: } E = \frac{\lambda}{2\pi\varepsilon r};\qquad \text{sheet: } E = \frac{\sigma}{2\varepsilon};\qquad \text{between plates: } E = \frac{\sigma}{\varepsilon} = \frac{V}{d}$', '$\text{V/m}$', 'Fields of the long line, the wide sheet and the parallel-plate gap.', '[{"symbol":"$\\lambda$","meaning":"charge per length","unit":"$\\text{C/m}$"},{"symbol":"$\\sigma$","meaning":"charge per area","unit":"$\\text{C/m}^2$"},{"symbol":"$\\varepsilon$","meaning":"permittivity, ε_rε₀","unit":"$\\text{F/m}$"}]'::jsonb, 'A line''s field falls as 1/r, a sheet''s doesn''t fall at all, a point''s as 1/r².', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'electric field' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
