SELECT gen_random_uuid()::text, 'formula', '$\oint \mathbf{D}\cdot d\mathbf{A} = Q_{enc}$', 'Gauss''s Law', '$\oint\mathbf{D}\cdot d\mathbf{A} = Q_{\text{enc}},\qquad \mathbf{D} = \varepsilon\mathbf{E}$', NULL, 'The electric flux out of any closed surface equals the charge inside: the quick route to fields with symmetry.', '[{"symbol":"$\\mathbf{D}$","meaning":"electric flux density","unit":"$\\text{C/m}^2$"},{"symbol":"$Q_{\\text{enc}}$","meaning":"charge inside the closed surface","unit":"$\\text{C}$"}]'::jsonb, 'Pick a surface on which E is constant (sphere, cylinder, pillbox). Charge outside contributes no net flux.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'gauss''s law' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
