SELECT gen_random_uuid()::text, 'formula', '$E = \frac{kQ}{r^2}\ (r \ge R)$', 'Field of a Charged Sphere', '$r \ge R: E = \frac{kQ}{r^2};\qquad r < R: E = 0 \text{ (conductor)},\ E = \frac{kQr}{R^3} \text{ (uniform solid)}$', '$\text{V/m}$', 'Outside, a charged sphere acts like a point charge; inside, a conductor has no field and a uniform solid one grows linearly.', '[{"symbol":"$Q$","meaning":"total charge","unit":"$\\text{C}$"},{"symbol":"$R$","meaning":"sphere radius","unit":"$\\text{m}$"},{"symbol":"$r$","meaning":"distance from the centre","unit":"$\\text{m}$"}]'::jsonb, 'All of a conductor''s excess charge sits on its surface.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'gauss''s law' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
