SELECT gen_random_uuid()::text, 'formula', '$V_{ab} = -\int_b^a\mathbf{E}\cdot d\mathbf{l}$', 'Potential and Field', '$V_a - V_b = -\int_b^a\mathbf{E}\cdot d\mathbf{l};\qquad \mathbf{E} = -\nabla V;\qquad \text{uniform: } E = \frac{V}{d}$', '$\text{V}$', 'Potential is the work per charge against the field; the field points downhill in potential.', '[{"symbol":"$\\mathbf{E}$","meaning":"electric field","unit":"$\\text{V/m}$"},{"symbol":"$d$","meaning":"distance along the field","unit":"$\\text{m}$"}]'::jsonb, 'Equipotential surfaces are always perpendicular to the field.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'electric potential' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
