SELECT gen_random_uuid()::text, 'formula', '$U = \frac{kq_1q_2}{r}$', 'Potential Energy of Two Charges', '$U = \frac{kq_1q_2}{r}$', '$\text{J}$', 'The work needed to bring two charges from far apart to separation r.', '[{"symbol":"$q_1, q_2$","meaning":"charges, with sign","unit":"$\\text{C}$"},{"symbol":"$r$","meaning":"separation","unit":"$\\text{m}$"}]'::jsonb, 'For several charges add U for every pair. Negative U means the pair attracts.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'electric potential' AND s."active"), NULL, false, 'PENDING', now(), now()
