SELECT gen_random_uuid()::text, 'formula', '$C = \frac{2\pi\varepsilon L}{\ln(b/a)}$', 'Coaxial and Spherical Capacitance', '$\text{coaxial: } C = \frac{2\pi\varepsilon L}{\ln(b/a)};\qquad \text{concentric spheres: } C = \frac{4\pi\varepsilon ab}{b - a};\qquad \text{isolated sphere: } 4\pi\varepsilon R$', '$\text{F}$', 'Capacitance of a cable and of spherical electrodes.', '[{"symbol":"$a, b$","meaning":"inner and outer radii","unit":"$\\text{m}$"},{"symbol":"$L$","meaning":"length","unit":"$\\text{m}$"},{"symbol":"$\\varepsilon$","meaning":"permittivity, ε_rε₀","unit":"$\\text{F/m}$"}]'::jsonb, 'Cable capacitance per km sets its charging current: I = ωCV.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'capacitance and dielectrics' AND s."active"), NULL, false, 'PENDING', now(), now()
