SELECT gen_random_uuid()::text, 'formula', '$w = \tfrac12\varepsilon E^2$', 'Energy Density of an Electric Field', '$w = \tfrac12\varepsilon E^2 = \tfrac12DE$', '$\text{J/m}^3$', 'Energy stored per cubic metre of an electric field.', '[{"symbol":"$\\varepsilon$","meaning":"permittivity, ε_rε₀","unit":"$\\text{F/m}$"},{"symbol":"$E$","meaning":"field strength","unit":"$\\text{V/m}$"}]'::jsonb, 'Times the gap volume Ad it gives a capacitor''s ½CV².', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'capacitance and dielectrics' AND s."active"), NULL, false, 'PENDING', now(), now()
