SELECT gen_random_uuid()::text, 'formula', '$J = nqv_d = \sigma E$', 'Current Density and Drift Velocity', '$J = \frac{I}{A} = nqv_d = \sigma E$', '$\text{A/m}^2$', 'Current per area, and how slowly the electrons actually drift.', '[{"symbol":"$n$","meaning":"free electrons per volume (copper 8.5 × 10²⁸)","unit":"$\\text{m}^{-3}$"},{"symbol":"$v_d$","meaning":"drift velocity","unit":"$\\text{m/s}$"},{"symbol":"$\\sigma$","meaning":"conductivity","unit":"$\\text{S/m}$"}]'::jsonb, 'Drift is a fraction of a millimetre per second; the signal travels near light speed.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'current and resistivity' AND s."active"), NULL, false, 'PENDING', now(), now()
