SELECT gen_random_uuid()::text, 'formula', '$R = \frac{\rho}{2\pi L}\ln\frac{b}{a}$', 'Insulation Resistance of a Cable', '$R = \frac{\rho}{2\pi L}\ln\frac{b}{a}$', '$\Omega$', 'Leakage resistance through a cable''s insulation, from conductor to sheath.', '[{"symbol":"$\\rho$","meaning":"insulation resistivity","unit":"$\\Omega\\cdot\\text{m}$"},{"symbol":"$a, b$","meaning":"conductor and outer insulation radii","unit":"$\\text{m}$"},{"symbol":"$L$","meaning":"cable length","unit":"$\\text{m}$"}]'::jsonb, 'It falls as the cable gets LONGER (more leakage paths in parallel), the opposite of conductor resistance.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'current and resistivity' AND s."active"), NULL, false, 'PENDING', now(), now()
