SELECT gen_random_uuid()::text, 'formula', '$d\mathbf{B}$', 'Biot-Savart Law', '$d\mathbf{B} = \frac{\mu_0}{4\pi}\frac{I\,d\mathbf{l}\times\hat{\mathbf{r}}}{r^2}$', '$\text{T}$', 'The field of a small piece of current; integrate along the conductor for the whole field.', '[{"symbol":"$I$","meaning":"current","unit":"$\\text{A}$"},{"symbol":"$d\\mathbf{l}$","meaning":"current element","unit":"$\\text{m}$"},{"symbol":"$r$","meaning":"distance to the field point","unit":"$\\text{m}$"}]'::jsonb, 'Like Coulomb''s law for magnetism: inverse square, but at right angles to both the current and r.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'biot-savart law' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
