SELECT gen_random_uuid()::text, 'formula', '$B = \frac{\mu_0NI}{2R}$', 'Field of a Circular Loop', '$\text{centre: } B = \frac{\mu_0NI}{2R};\qquad \text{on the axis: } B = \frac{\mu_0NIR^2}{2(R^2 + x^2)^{3/2}}$', '$\text{T}$', 'The field at the centre and along the axis of a current loop.', '[{"symbol":"$N$","meaning":"turns","unit":null},{"symbol":"$I$","meaning":"current","unit":"$\\text{A}$"},{"symbol":"$R$","meaning":"loop radius","unit":"$\\text{m}$"},{"symbol":"$x$","meaning":"distance along the axis","unit":"$\\text{m}$"}]'::jsonb, 'Compare a long wire: μ₀I/(2πr). The loop is π times stronger at the same distance R.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'biot-savart law' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
