SELECT gen_random_uuid()::text, 'formula', '$\oint\mathbf{H}\cdot d\mathbf{l} = I_{enc}$', 'Ampère''s Circuital Law', '$\oint\mathbf{H}\cdot d\mathbf{l} = I_{\text{enc}},\qquad \mathbf{B} = \mu\mathbf{H}$', NULL, 'The circulation of H around any closed path equals the current it encloses: the quick route to fields with symmetry.', '[{"symbol":"$\\mathbf{H}$","meaning":"magnetic field intensity","unit":"$\\text{A/m}$"},{"symbol":"$I_{\\text{enc}}$","meaning":"current through the loop (N I for a coil)","unit":"$\\text{A}$"}]'::jsonb, 'Inside a long solid wire: B = μ₀Ir/(2πR²), growing from zero at the centre.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'ampère''s law' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
