SELECT gen_random_uuid()::text, 'formula', '$B = \frac{\mu NI}{l}$', 'Field of a Solenoid and a Toroid', '$\text{long solenoid: } B = \frac{\mu NI}{l};\qquad \text{toroid: } B = \frac{\mu NI}{2\pi r}$', '$\text{T}$', 'The nearly uniform field inside a long coil and a ring-shaped coil.', '[{"symbol":"$N$","meaning":"turns","unit":null},{"symbol":"$I$","meaning":"current","unit":"$\\text{A}$"},{"symbol":"$l$","meaning":"solenoid length","unit":"$\\text{m}$"},{"symbol":"$r$","meaning":"radius within the toroid","unit":"$\\text{m}$"},{"symbol":"$\\mu$","meaning":"permeability, μ_rμ₀","unit":"$\\text{H/m}$"}]'::jsonb, 'Outside an ideal toroid B = 0: it keeps its flux entirely inside.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'ampère''s law' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
