SELECT gen_random_uuid()::text, 'formula', '$P_h = k_hfB_m^n V,\ P_e = k_ef^2B_m^2t^2V$', 'Core Losses (Hysteresis and Eddy Current)', '$P_h = k_hfB_m^nV\ (n \approx 1.6);\qquad P_e = k_ef^2B_m^2t^2V$', '$\text{W}$', 'Iron losses in a core: hysteresis (the B-H loop''s area each cycle) and eddy currents.', '[{"symbol":"$f$","meaning":"frequency","unit":"$\\text{Hz}$"},{"symbol":"$B_m$","meaning":"peak flux density","unit":"$\\text{T}$"},{"symbol":"$t$","meaning":"lamination thickness","unit":"$\\text{m}$"},{"symbol":"$V$","meaning":"core volume","unit":"$\\text{m}^3$"}]'::jsonb, 'Doubling f doubles hysteresis loss but quadruples eddy loss. Thin laminations cut eddy loss as t².', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'magnetic materials and hysteresis' AND s."active"), NULL, false, 'PENDING', now(), now()
