SELECT gen_random_uuid()::text, 'formula', '$w = \frac{B^2}{2\mu}$', 'Magnetic Energy Density', '$w = \frac{B^2}{2\mu} = \tfrac12BH$', '$\text{J/m}^3$', 'Energy stored per cubic metre of magnetic field.', '[{"symbol":"$B$","meaning":"flux density","unit":"$\\text{T}$"},{"symbol":"$\\mu$","meaning":"permeability, μ_rμ₀","unit":"$\\text{H/m}$"}]'::jsonb, 'For the same B an air gap stores μᵣ times more energy than iron: most of a gapped inductor''s energy is in the gap.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'magnetic materials and hysteresis' AND s."active"), NULL, false, 'PENDING', now(), now()
