SELECT gen_random_uuid()::text, 'formula', '$NI = \Phi(\mathcal{R}_c + \mathcal{R}_g)$', 'Magnetic Circuit with an Air Gap', '$NI = H_cl_c + H_gl_g = \Phi(\mathcal{R}_c + \mathcal{R}_g),\qquad H_g = \frac{B}{\mu_0}$', '$\text{A}\cdot\text{t}$', 'A series magnetic circuit: core and gap reluctances add like resistors.', '[{"symbol":"$l_c, l_g$","meaning":"core path and gap lengths","unit":"$\\text{m}$"},{"symbol":"$\\Phi$","meaning":"flux","unit":"$\\text{Wb}$"}]'::jsonb, 'A 1 mm gap can need more ampere-turns than a metre of steel. Fringing makes the gap''s effective area a bit larger.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'magnetic circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
