SELECT gen_random_uuid()::text, 'formula', '$e = NBA\omega\sin\omega t$', 'EMF of a Rotating Coil', '$e = NBA\omega\sin\omega t,\qquad E_m = NBA\omega = 2\pi fN\Phi_m,\qquad E_{rms} = 4.44fN\Phi_m$', '$\text{V}$', 'The sinusoidal EMF of a coil turning in a uniform field: the basis of the ac generator.', '[{"symbol":"$N$","meaning":"turns","unit":null},{"symbol":"$B$","meaning":"flux density","unit":"$\\text{T}$"},{"symbol":"$A$","meaning":"coil area","unit":"$\\text{m}^2$"},{"symbol":"$\\omega$","meaning":"angular speed","unit":"$\\text{rad/s}$"}]'::jsonb, 'The EMF is greatest when the coil''s plane lies ALONG the field (flux zero, changing fastest).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'faraday''s law' AND s."active"), NULL, false, 'PENDING', now(), now()
