SELECT gen_random_uuid()::text, 'formula', '$T = NBIA\sin\theta$', 'Torque on a Current Loop', '$T = NBIA\sin\theta$', '$\text{N}\cdot\text{m}$', 'The torque that turns a coil in a field: the principle of motors and moving-coil meters.', '[{"symbol":"$N$","meaning":"turns","unit":null},{"symbol":"$B$","meaning":"flux density","unit":"$\\text{T}$"},{"symbol":"$I$","meaning":"current","unit":"$\\text{A}$"},{"symbol":"$A$","meaning":"loop area","unit":"$\\text{m}^2$"},{"symbol":"$\\theta$","meaning":"angle between the loop''s normal and B","unit":null}]'::jsonb, 'Greatest when the plane of the coil lies along the field; zero when it faces the field.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'force on conductors' AND s."active"), NULL, false, 'PENDING', now(), now()
