SELECT gen_random_uuid()::text, 'formula', '$v = \frac{1}{\sqrt{\mu\varepsilon}}$', 'Wave Speed and Intrinsic Impedance', '$v = \frac{1}{\sqrt{\mu\varepsilon}} = \frac{c}{\sqrt{\mu_r\varepsilon_r}},\qquad \eta = \sqrt{\frac{\mu}{\varepsilon}},\ \eta_0 \approx 377\ \Omega,\qquad \lambda = \frac{v}{f}$', '$\text{m/s}$', 'How fast a wave travels in a medium, its wavelength, and the ratio E/H it carries.', '[{"symbol":"$\\mu$","meaning":"permeability, μ_rμ₀","unit":"$\\text{H/m}$"},{"symbol":"$\\varepsilon$","meaning":"permittivity, ε_rε₀","unit":"$\\text{F/m}$"},{"symbol":"$f$","meaning":"frequency","unit":"$\\text{Hz}$"}]'::jsonb, 'In a dielectric with εᵣ = 4 the wave travels at half the speed of light, with half the wavelength.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE' AND s."normKey" = 'electromagnetic waves' AND s."active"), NULL, false, 'PENDING', now(), now()
